<script setup lang="ts">
import { computed, onMounted, shallowRef, watch } from 'vue'
import { workbenchRequest } from '../../api/workbench'
import type { EvaluationCase, WorkbenchRun } from '../../types/workbench'
import { isolatedDemo } from '../../utils/runtime'
defineProps<{ disabled: boolean; canOperate: boolean }>()
const emit = defineEmits<{ created: [run: WorkbenchRun] }>()
const cases = shallowRef<EvaluationCase[]>([]), mode = shallowRef<'retrieval' | 'agent'>('retrieval'), selected = shallowRef<string[]>([]), consent = shallowRef(false), busy = shallowRef(false), error = shallowRef('')
const modelProfile=shallowRef('primary'),promptProfile=shallowRef('standard'),secondaryAvailable=shallowRef(false)
const visible = computed(() => cases.value.filter(c => mode.value === 'agent' || c.section))
watch(mode, () => { selected.value = []; consent.value = false })
function toggle(id: string, checked: boolean) { selected.value = checked ? [...selected.value, id] : selected.value.filter(v => v !== id) }
async function start() { if (busy.value) return; busy.value = true; error.value = ''; try { const run = await workbenchRequest<WorkbenchRun>('/evaluations', { request_id: crypto.randomUUID(), evaluation_mode: mode.value, case_ids: selected.value, variants: mode.value === 'retrieval' ? ['semantic','hybrid'] : ['baseline','rag'], external_allowed: consent.value, model_profile:modelProfile.value, prompt_profile:promptProfile.value }, 'POST'); emit('created', run) } catch (e) { error.value = String(e) } finally { busy.value = false } }
onMounted(async () => { try { const config=await workbenchRequest<{secondary_model_configured:boolean}>('/config');secondaryAvailable.value=config.secondary_model_configured;cases.value = await workbenchRequest<EvaluationCase[]>('/cases') } catch (e) { error.value = String(e) } })
</script>
<template><section class="evaluation"><h2>效果评测与版本对照</h2><p>固定用例为开发回归集，不是独立保留测试集。检索对照不调用大模型；Agent对照会真实运行“直接回答基线”和“RAG+只读工具”，没有写工具。词语和工具断言不等于事实正确率，安全用例需人工复核。</p><p v-if="error" role="alert">{{ error }}</p><label>评测方式<select v-model="mode" :disabled="disabled || busy"><option value="retrieval">本地检索：语义 vs 混合排序</option><option value="agent" :disabled="!canOperate || isolatedDemo">真实Agent：直接回答 vs RAG与工具</option></select></label><p v-if="mode === 'agent'">每次最多4条；每账号24小时最多60次模型调用尝试。模型、提示词和知识版本随运行记录保存，不自动发送全部问题。</p><label v-if="mode === 'agent'">模型配置<select v-model="modelProfile"><option value="primary">当前配置模型</option><option value="secondary" :disabled="!secondaryAvailable">服务端第二模型（需预先配置）</option></select></label><label v-if="mode === 'agent'">提示词配置<select v-model="promptProfile"><option value="standard">标准问题</option><option value="structured">事实/依据/未知/下一步</option></select></label><fieldset :disabled="disabled || busy"><label v-for="c in visible" :key="c.id" class="case"><input type="checkbox" :checked="selected.includes(c.id)" @change="toggle(c.id, ($event.target as HTMLInputElement).checked)">{{ c.id }} · {{ c.category }} · {{ c.question }}</label></fieldset><label v-if="mode === 'agent'"><input v-model="consent" type="checkbox">授权本次用例、查询结果及检索证据发送给外部模型，并承担调用费用</label><button :disabled="disabled || busy || !selected.length || (mode === 'agent' && (!consent || selected.length > 4 || !canOperate))" @click="start">运行选中用例的对照评测</button></section></template>
<style scoped>.evaluation{padding:20px;background:#102537;border:1px solid #31546b}.evaluation p{color:#9ebfd2;line-height:1.8}.evaluation select{padding:8px;background:#081c2a;color:#fff}.case{display:block;padding:8px;border-bottom:1px solid #31546b;font-size:13px}fieldset{border:0;padding:0;margin:12px 0}</style>
